import { 
  MeshBasicNodeMaterial, 
  MeshStandardNodeMaterial, 
  BoxGeometry, 
  PlaneGeometry, 
  SRGBColorSpace, 
  Group, 
  Vector3, 
  PointLight 
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep, val } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // --- STAGE AND BACKDROP ---
  const backdropGeo = new PlaneGeometry(12, 10);
  const backdropMat = new MeshBasicNodeMaterial();
  const vUv = uv();
  const backgroundGrad = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10
    vec3(0.078, 0.078, 0.102), // #14141a
    vUv.y
  );
  backdropMat.colorNode = backgroundGrad;
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- LOCAL LIGHTS ---
  const keyLight = new PointLight('#e8ecf2', 1.2, 8);
  keyLight.position.set(-2, 2, 2);
  group.add(keyLight);

  const rimLight = new PointLight('#ff2a38', 0.8, 6);
  rimLight.position.set(2, -2, 1);
  group.add(rimLight);

  // --- TEXT CREATION ---
  const textContainer = new Group();
  group.add(textContainer);

  const headlineText = ctx.fontAtlas.createText("Inside the atelier", {
    fontSize: 0.34, // Sized dynamically inside range
    color: colors.paper,
    align: 'left'
  });
  headlineText.position.set(-2.2, 1.9, 0.1);
  textContainer.add(headlineText);

  const labels = [
    "DIAL ROOM",
    "ESCAPEMENT BENCH",
    "CNC HALL",
    "FINISHING LAB",
    "ARCHIVE VAULT",
    "ASSEMBLY LINE ONE"
  ];

  const labelObjects = [];
  labels.forEach((text) => {
    const labelMesh = ctx.fontAtlas.createText(text, {
      fontSize: 0.09,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 6
    });
    labelMesh.position.set(-2.2, 0, 0.1);
    labelMesh.visible = false;
    textContainer.add(labelMesh);
    labelObjects.push(labelMesh);
  });

  // --- LOOP COLUMN GALLERY SETUP ---
  const columnGroup = new Group();
  columnGroup.position.x = 0.9;
  group.add(columnGroup);

  const plateCount = 6;
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const pitch = 1.5;
  const totalHeight = plateCount * pitch; // 9.0 units
  const plates = [];

  const plateGeo = new BoxGeometry(plateWidth, plateHeight, 0.05);
  // Separate geo for accent strip to allow high emissive without blowing main plate
  const accentStripGeo = new BoxGeometry(0.03, plateHeight, 0.06);

  const bevelGeo = new BoxGeometry(plateWidth + 0.04, plateHeight + 0.04, 0.03);
  const bevelMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.5,
    metalness: 0.5
  });

  // Load baseline/variant textures
  const textures = [];
  for (let i = 0; i < plateCount; i++) {
    textures[i] = null;
  }

  const baseImageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(baseImageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    for (let i = 0; i < plateCount; i++) {
      textures[i] = tex.clone();
      // Apply offset to visually differentiate plates
      textures[i].offset.set((i * 0.15) % 0.4, (i * 0.1) % 0.3);
      textures[i].repeat.set(0.85, 0.85);
      textures[i].needsUpdate = true;
    }
  });

  for (let i = 0; i < plateCount; i++) {
    const plateContainer = new Group();
    plateContainer.position.y = i * pitch - (totalHeight / 2);

    // Bevel Backing
    const bevelMesh = new THREE.Mesh(bevelGeo, bevelMat);
    bevelMesh.position.z = -0.02;
    plateContainer.add(bevelMesh);

    // Standard Plate Body
    const plateMat = new MeshStandardNodeMaterial({
      color: '#e8ecf2',
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });
    const plateMesh = new THREE.Mesh(plateGeo, plateMat);
    plateContainer.add(plateMesh);

    // Lazy apply texture once loaded
    ctx.textureLoader.loadTexture(baseImageUrl).then(() => {
      if (textures[i]) {
        plateMat.map = textures[i];
        plateMat.needsUpdate = true;
      }
    });

    // Emissive Signal Accent Strip (Left Side)
    const accentMat = new MeshStandardNodeMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.4,
      roughness: 0.2
    });
    const accentStrip = new THREE.Mesh(accentStripGeo, accentMat);
    accentStrip.position.set(-plateWidth / 2 - 0.015, 0, 0.01);
    accentStrip.visible = false;
    plateContainer.add(accentStrip);

    columnGroup.add(plateContainer);
    plates.push({
      container: plateContainer,
      accent: accentStrip,
      originalY: i * pitch,
      index: i
    });
  }

  // --- SCROLL INTERACTIVE LOOP LOGIC ---
  let scrollTargetY = 0;
  let scrollCurrentY = 0;
  const damping = 0.12;

  const onScroll = (event) => {
    const delta = event.deltaY || 0;
    scrollTargetY -= (delta * 0.003) * pitch;
  };

  const updateLoop = () => {
    // Standard weighted inertia
    scrollCurrentY += (scrollTargetY - scrollCurrentY) * damping;

    // Apply modular loop on column group position
    columnGroup.position.y = scrollCurrentY;

    let closestPlate = null;
    let minDistance = Infinity;

    plates.forEach((plate) => {
      // Calculate absolute world-like position for modulo
      let worldY = columnGroup.position.y + plate.originalY;

      // Wrap around within viewport bounds
      const halfHeight = totalHeight / 2;
      worldY = ((worldY + halfHeight) % totalHeight);
      if (worldY < 0) worldY += totalHeight;
      worldY -= halfHeight;

      plate.container.position.y = worldY - columnGroup.position.y;

      const dist = Math.abs(worldY);
      if (dist < minDistance) {
        minDistance = dist;
        closestPlate = plate;
      }
    });

    // Update highlights and labels with weighted settles
    plates.forEach((plate) => {
      const isFocused = plate === closestPlate;

      gsap.to(plate.container.scale, {
        x: isFocused ? 1.06 : 1.0,
        y: isFocused ? 1.06 : 1.0,
        z: isFocused ? 1.06 : 1.0,
        duration: 0.35,
        ease: 'power2.out'
      });

      plate.accent.visible = isFocused;

      const label = labelObjects[plate.index];
      if (label) {
        label.visible = isFocused;
        if (isFocused) {
          gsap.to(label.position, {
            y: plate.container.position.y + columnGroup.position.y,
            duration: 0.2,
            overwrite: 'auto'
          });
        }
      }
    });
  };

  // Add scroll listener safely using virtualized handler hook
  group.userData.handlers = {
    wheel: onScroll
  };

  // GSAP Ticker for interactive loop updating
  gsap.ticker.add(updateLoop);

  // --- PRIMITIVES ENTRY ---
  let flyThroughCtrl = null;
  if (ctx.primitives && ctx.primitives['fly-through']) {
    flyThroughCtrl = ctx.primitives['fly-through'](group, { depthUnits: 2.5 });
  }

  // --- CLEANUP DISPOSAL ---
  group.userData.cleanup = () => {
    gsap.ticker.remove(updateLoop);
    if (flyThroughCtrl && flyThroughCtrl.cleanup) {
      flyThroughCtrl.cleanup();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    plateGeo.dispose();
    accentStripGeo.dispose();
    bevelGeo.dispose();
    bevelMat.dispose();
    textures.forEach((t) => t && t.dispose());
  };

  return group;
}
